raw:
{
  "spells": [
    {
      "id": "spell_fire_04",
      "theory": "驯灶术将魔力沿锅底与灶膛间的热流铺开，使火焰反复点燃同一股燃气，从而让每次燃烧更充分。魔力并不制造新燃料，只是让已有柴炭释放的热量更集中地留在锅底。灶膛结构越规整，效果越明显；若烟道堵塞或柴薪潮湿，术法只能减少浪费，不能凭空补足热量。",
      "casting": "施术者蹲在灶口，用火钳在炭层上划出三道平行浅沟，同时向沟底缓缓送入魔力，直到火焰由跳动摇摆转为平稳贴锅。",
      "failure": "魔力送入过快时，火焰会突然蹿高又缩回，锅底留下一圈黑烟。灶膛内可能发出闷响，湿柴被引燃后冒出刺鼻白烟，但不会造成爆炸或飞出火星。",
      "counters": [
        "往灶膛撒一把湿灰，可让火焰暂时回到普通燃烧状态。",
        "抽掉一根主要柴薪，破坏热流路径，术法效果随即减弱。"
      ],
      "socialConsequences": "河谷农户常请邻里见证驯灶术的施放，以确认灶火稳定、节省柴薪。城镇面包师依赖它控制烤炉温度，但公会要求施术者登记，以便在烤焦货物时追查责任。港口伙食船则看重燃料节省，却担心术法掩盖烟道隐患，因此船主会要求先清理烟道再施术。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常需反复调整炭沟，火焰仍会轻微跳动。",
        "熟练后能稳定维持火候，燃料节省接近一成。",
        "更精熟者能根据锅底形状调整热流，减少局部焦糊。",
        "极高熟练度下火焰几乎不晃，但节省上限仍为一成。"
      ]
    },
    {
      "id": "spell_fire_05",
      "theory": "炭纹测温把魔力灌入一根细炭线，使炭线随接触面的温度改变颜色深浅。热量沿炭线传导，施术者通过颜色变化判断器壁温差。炭线必须紧贴器具，否则空气间隙会阻断热流，读出的温度只是炭线自身的温度。它不能穿透布料或墙壁，也不能远距离读取。",
      "casting": "取一根干燥炭线，一端用手指按在待测器具表面，另一端捏在掌心，缓慢送入魔力并观察炭线由黑转红再转灰白的过程。",
      "failure": "炭线受潮时会先冒出细小水泡，颜色斑驳不定，读数失去意义。若按压不紧，炭线只微微发热，无法显示器壁温差，施术者可能误判为温度均匀。",
      "counters": [
        "在炭线与器具之间垫一片湿布，热流被阻断，读数失效。",
        "用凉水擦拭器具表面，使温差暂时消失，炭线颜色趋同。"
      ],
      "socialConsequences": "河谷铁匠用炭纹测温判断锻件回火程度，乡约允许在公共锻坊内施放。中陆城市的面包师和酿酒师依赖它监控发酵温度，公会要求持证者操作，以免误读导致整批货物报废。琥珀海岸的船主用它检查货舱是否过热，港务规定读数记录须随货单保存，以便货损时追责。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学者常因按压不稳而得到斑驳色纹，需多次重试。",
        "熟练者能稳定读出器壁温差，误差缩小到可接受范围。",
        "精熟者可根据炭线颜色变化速度判断升温快慢。",
        "极高熟练度下读数几乎与器具同步，但仍须直接接触。"
      ]
    },
    {
      "id": "spell_fire_06",
      "theory": "火线术把魔力压入地面，使一条两米长的浅沟中的可燃微粒持续阴燃，形成低矮火墙。火焰依赖地表已有的干燥碎屑，若地面潮湿或铺石，术法只能维持微弱火星。火线不追逐目标，也不自动蔓延，只是一道固定屏障，遇水则熄。",
      "casting": "以脚跟在地面划出两米直线，指尖沿沟撒入魔力，同时低声念出短促音节，直到沟内泛起均匀红光。",
      "failure": "魔力分布不均时，火线会断成数截，中间留下可通行的缺口。若地面过湿，火线只冒白烟而不起明火，施术者可能吸入烟气而咳嗽，但不会灼伤自身。",
      "counters": [
        "泼一桶水或沙土覆盖火线，阴燃随即熄灭。",
        "用湿布拖过地面，带走可燃微粒，火线无法维持。"
      ],
      "socialConsequences": "河谷牧人用火线术临时圈住走失的牲畜，乡约允许在远离草垛的空地施放。中陆城市的夜市摊主偶尔用它隔开拥挤人群，但公会要求施术者确保地面无易燃杂物，否则按纵火追究。琥珀海岸的码头工人用它封锁泄漏的货油区域，港务规定施术后须立即报告并清理残烬，以免复燃。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学者划出的火线常断成数截，需要补画多次。",
        "熟练者能维持两米火线完整燃烧，缺口明显减少。",
        "精熟者可控制火线高度，使其稳定在低矮范围。",
        "极高熟练度下火线边缘整齐，但长度与持续时间不变。"
      ]
    }
  ]
}
